fn locate<'a>(mut node:Node<'a>,path:&[usize])->Result<(Node<'a>,usize),ValueError>{for(position,&index)in path.iter().enumerate(){if matches!(node,Node::Domain(_)|Node::Intrinsic(_)|Node::Receiving(_)){return Ok((node,position))}node=node.child(index)?}Ok((node,path.len()))}
fn view<'a>(node:Node<'a>,path:&[usize])->Result<V<'a>,ValueError>{let(node,position)=locate(node,path)?;match node{Node::Receiving(r)=>super::native_snapshot_projection::project_complete_original_receiving(r,&path[position..]),Node::Domain(d)=>d.projection().projection_view(&path[position..]),Node::Intrinsic(d)=>intrinsic_view(d,&path[position..]),node=>node.view()}}
fn key<'a>(node:Node<'a>,path:&[usize],index:usize)->Result<&'a str,ValueError>{let(node,position)=locate(node,path)?;match node{Node::Receiving(r)=>super::native_snapshot_projection::key_complete_original_receiving(r,&path[position..],index),Node::Domain(d)=>d.projection().projection_key(&path[position..],index),Node::Intrinsic(d)=>super::OriginalDomainProjection::projection_key(d,&path[position..],index),node=>node.key(index)}}
/// 🧳️ Borrows the exact Source close cause and its original owner.
pub fn project_original_source_close_failure<'a>(error:&'a OriginalSourceCloseFailure,path:&[usize])->Result<V<'a>,ValueError>{view(Node::SourceClose(error),path)}
/// 🔑️ Borrows a Source close cause field name.
pub fn key_original_source_close_failure<'a>(error:&'a OriginalSourceCloseFailure,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::SourceClose(error),path,index)}
/// 🪢️ Borrows primary, receipt and context owners including complete nested domain fields.
pub fn project_original_turn_failure<'a>(error:&'a OriginalTurnFailure,path:&[usize])->Result<V<'a>,ValueError>{view(Node::Turn(error),path)}
pub fn key_original_turn_failure<'a>(error:&'a OriginalTurnFailure,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::Turn(error),path,index)}
/// 🧯️ Borrows exact native refusal kind, original text and independent retained effects.
pub fn project_original_value_error<'a>(error:&'a ValueError,path:&[usize])->Result<V<'a>,ValueError>{view(Node::Value(error),path)}
pub fn key_original_value_error<'a>(error:&'a ValueError,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::Value(error),path,index)}

/// 🚨️ Borrows every original diagnostic field through the same canonical ordinal projection.
pub fn project_original_fault<'a>(error:&'a Fault,path:&[usize])->Result<V<'a>,ValueError>{view(Node::Fault(error),path)}
/// 🔑️ Borrows the original diagnostic key without allocating a representation.
pub fn key_original_fault<'a>(error:&'a Fault,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::Fault(error),path,index)}
/// ♻️ Borrows every original retirement role and nested child without a diagnostic mirror.
pub fn project_original_retirement_failure<'a>(error:&'a OriginalRetirementFailure,path:&[usize])->Result<V<'a>,ValueError>{view(Node::Retirement(error),path)}
/// 🔑️ Borrows the selected original retirement field name.
pub fn key_original_retirement_failure<'a>(error:&'a OriginalRetirementFailure,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::Retirement(error),path,index)}
/// 🪢️ Borrows both complete original owners without allocating a diagnostic representation.
pub fn project_original_retirement_receiving<'a>(error:&'a OriginalRetirementReceivingPrimary,path:&[usize])->Result<V<'a>,ValueError>{view(Node::RetirementReceiving(error),path)}
/// 🔑️ Borrows a field name from the combined original owners.
pub fn key_original_retirement_receiving<'a>(error:&'a OriginalRetirementReceivingPrimary,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::RetirementReceiving(error),path,index)}
/// 🛬️ Borrows the original receiving subtree without allocating a prefixed path.
pub fn project_original_receiving_primary<'a>(error:&'a OriginalReceivingPrimary,path:&[usize])->Result<V<'a>,ValueError>{view(Node::Receiving(error),path)}
/// 🔑️ Borrows an original receiving field name at its unchanged relative path.
pub fn key_original_receiving_primary<'a>(error:&'a OriginalReceivingPrimary,path:&[usize],index:usize)->Result<&'a str,ValueError>{key(Node::Receiving(error),path,index)}
impl super::OriginalDomainProjection for OriginalTurnFailure{
 fn projection_identity(&self)->usize{self as*const Self as usize}
 fn projection_view(&self,path:&[usize])->Result<V<'_>,ValueError>{project_original_turn_failure(self,path)}
 fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{key_original_turn_failure(self,path,index)}
}

fn intrinsic_view<'a>(source:&'a semio_framework_value_retained_clone::DslValue,path:&[usize])->Result<V<'a>,ValueError>{super::OriginalDomainProjection::projection_view(source,path)}
